class Solution {
    public long palindromeCensus(String s) {
        int n = s.length();
        long total = 0;
        for (int c = 0; c < 2 * n - 1; c++) {
            int i = c / 2, j = c / 2 + c % 2;
            while (i >= 0 && j < n && s.charAt(i) == s.charAt(j)) { total++; i--; j++; }
        }
        return total;
    }
}

