long long palindromeCensus(char* s) {
    int n = strlen(s), m = 2 * n + 3;
    char* t = malloc(m + 1);
    t[0] = '^';
    for (int i = 0; i < n; i++) { t[2 * i + 1] = '#'; t[2 * i + 2] = s[i]; }
    t[2 * n + 1] = '#';
    t[m - 1] = '$';
    t[m] = '\0';
    int* p = calloc(m, sizeof(int));
    int center = 0, right = 0;
    long long total = 0;
    for (int i = 1; i < m - 1; i++) {
        if (i < right) p[i] = right - i < p[2 * center - i] ? right - i : p[2 * center - i];
        while (t[i + p[i] + 1] == t[i - p[i] - 1]) p[i]++;
        if (i + p[i] > right) { center = i; right = i + p[i]; }
        total += (p[i] + 1) / 2;
    }
    free(t); free(p);
    return total;
}
